update public.posts set title_en='Shravanabelagola: a living heritage',summary_en='From the presence of Bahubali atop the hill to the sculptural artistry of the basadis — a closer look at our Jain heritage.',body_en='<p>From the presence of Bahubali atop the hill to the sculptural artistry of the basadis — a closer look at our Jain heritage.</p><p>This is a sample article introducing our community''s heritage, faith and values. Through this page you can see how a report reads, how event dates appear and how related topics are surfaced.</p><h2>Carrying the tradition forward</h2><p>Ahimsa, coexistence and service hold a special place in Jain culture. Recording the history of our towns and the achievements of our community is an invaluable gift to the next generation.</p><p>The content here is only a sample prepared to demonstrate the design. Real reports and event details will be published after editorial review.</p>' where id='00000000-0000-4000-8000-000000001000';
